/bin/bash -lc "python3 - <<'PY'
import json
import pathlib
import subprocess
import tempfile

def run(script, *args):
    result = subprocess.run(
        [\"node\", \"--input-type=module\", \"-e\",
         \"import { loadCatalog, setPinned, saveCatalog } from './catalog/src/catalog.mjs';\\n\" + script,
         *map(str, args)], check=True, capture_output=True, text=True,
    )
    return json.loads(result.stdout)

def card(id, title, pinned):
    return dict(id=id, title=title, pinned=pinned)

with tempfile.TemporaryDirectory(dir=\".\", prefix=\".accept-catalog.\") as tmp:
    path = pathlib.Path(tmp) / \"data.json\"
    for scenario, before, id, value in [
        (\"pin\", [card(\"c\", \"Caffè\", True), card(\"a\", \"Ива\", False), card(\"b\", \"Beta\", False)], \"a\", True),
        (\"unpin\", [card(\"z\", \"Zeta\", False), card(\"b\", \"Beta\", True), card(\"a\", \"Alpha\", False)], \"b\", False),
    ]:
        path.write_text(json.dumps(before), encoding=\"utf-8\")
        expected = [{**item, \"pinned\": value} if item[\"id\"] == id else item for item in before]
        session = run(\"\"\"
          const [path, id, value] = process.argv.slice(1);
          const loaded = loadCatalog(path);
          const changed = setPinned(loaded, id, JSON.parse(value));
          saveCatalog(path, changed);
          console.log(JSON.stringify({loaded, changed}));
        \"\"\", path, id, json.dumps(value))
        saved = json.loads(path.read_text(encoding=\"utf-8\"))
        reloaded = run(\"console.log(JSON.stringify(loadCatalog(process.argv[1])));\", path)
        assert session[\"loaded\"] == before
        assert session[\"changed\"] == expected
        assert [(x[\"id\"], x[\"title\"]) for x in reloaded] == [(x[\"id\"], x[\"title\"]) for x in before]
        print(json.dumps(dict(scenario=scenario, expected=expected, saved=saved, reloaded=reloaded,
                              full_reload_matches=reloaded == expected), ensure_ascii=False))

    path.write_text('[{\"id\":\"old\",\"title\":\"Legacy\"},{\"id\":\"live\",\"title\":\"Current\",\"pinned\":true}]', encoding=\"utf-8\")
    loaded = run(\"console.log(JSON.stringify(loadCatalog(process.argv[1])));\", path)
    assert loaded == [card(\"old\", \"Legacy\", False), card(\"live\", \"Current\", True)]
    print(\"legacy:\", loaded)
    original = path.read_bytes()
    missing = run(\"\"\"
      const path = process.argv[1];
      try {
        saveCatalog(path, setPinned(loadCatalog(path), 'missing', true));
        console.log(JSON.stringify({succeeded: true}));
      } catch (error) {
        console.log(JSON.stringify({succeeded: false, message: error.message}));
      }
    \"\"\", path)
    assert missing == dict(succeeded=False, message=\"Unknown card: missing\")
    assert path.read_bytes() == original
    print(\"missing:\", missing, \"file unchanged\")
PY"

